/** Both ends of a range are inclusive. A range that ends before it starts is refused. */
function assertChronologicalRange(
  since: string | undefined,
  until: string | undefined,
): void {
  if (since === undefined || until === undefined) return;
  if (Date.parse(until) < Date.parse(since)) {
    throw new Error("Time range ends before it starts");
  }
}

