/**
 * Every row in the filter, newest first. Pages by the keyset cursor rather
 * than by timestamp: many rows of one fan-out share an `occurredAt`, and
 * shrinking `until` to the oldest stamp on a page would stop there.
 */
async function listAllActivity(
  input: Omit<ActivityFilterInput, "limit" | "cursor">,
): Promise<readonly ActivityEvent[]> {
  const items: ActivityEvent[] = [];
  let cursor: string | null = null;

  for (;;) {
    const page = await activityRepo.listActivity({
      ...input,
      limit: EXPORT_PAGE_SIZE,
      cursor,
    });
    items.push(...page.items);
    if (page.nextCursor === null || page.nextCursor === cursor) break;
    cursor = page.nextCursor;
  }

  return items;
}

